__END_L_5__
)
LISTS=("master.dnf:L_0" "sys-firewall.dnf:L_1" "sys-killswitch.dnf:L_2" "sys-net.dnf:L_3" "sys-usb.dnf:L_4" "sys-vpn.dnf:L_5")

# ------------------------------------------------------------------ helpers
ask() {   # ask "question" -> 0 for yes
    local a
    read -r -p "$1 [y/N] " a
    [[ $a =~ ^[Yy]([Ee][Ss])?$ ]]
}
names() {   # package names from a list: comments and blank lines removed
    printf '%s\n' "$1" | sed 's/#.*//' | tr -s '[:space:]' ' '
}
check_names() {
    local p
    for p in $1; do
        [[ $p =~ ^[A-Za-z0-9][A-Za-z0-9._+-]*$ ]] || { echo "bad package name: $p" >&2; exit 1; }
    done
}
in_vm() {   # in_vm <qube> <command>   (as root, stdin passed through)
    qvm-run --user root --pass-io --no-gui "$1" "$2"
}
push() {    # push <qube> <path> <mode>   (content on stdin)
    in_vm "$1" "mkdir -p \"\$(dirname '$2')\" && cat > '$2.new' && chown root:root '$2.new' && chmod $3 '$2.new' && mv -f '$2.new' '$2'"
}

# ------------------------------------------------------------------ 0. questions
echo "Minimal templating setup. All questions first; then it runs on its own."
echo
DO_SWITCH=0
echo "Near the end, the switch-over shuts down ALL running qubes, makes every"
echo "sys- qube a named disposable (app qubes kept as <name>-old), and starts"
echo "the sys- qubes again. SAVE ALL OPEN FILES IN EVERY QUBE before it gets there."
ask "Do the switch-over?" && DO_SWITCH=1
echo
echo "Running: switch-over=$DO_SWITCH"
echo

# ------------------------------------------------------------------ 1. watcher off
echo "== watcher"
if systemctl --user is-active --quiet "$UNIT" 2>/dev/null || \
   systemctl --user is-enabled --quiet "$UNIT" 2>/dev/null; then
    systemctl --user disable --now "$UNIT"
    echo "   stopped for setup (enabled again at the end)"
else
    echo "   not running"
fi

# ------------------------------------------------------------------ 2. dom0 files
echo "== dom0 files"
mkdir -p "$BIN" "$CONF_DIR" "$UNIT_DIR" "$STATE_DIR"
printf '%s\n' "$F_MAIN"   > "$BIN/minimal-templating"
printf '%s\n' "$F_LISTEN" > "$BIN/minimal-templating-listen"
chmod 0755 "$BIN/minimal-templating" "$BIN/minimal-templating-listen"
printf '%s\n' "$F_UNIT"   > "$UNIT_DIR/$UNIT"
printf '%s\n' "$F_CONF"   > "$CONF_DIR/templates.conf.example"
if [ -f "$CONF_DIR/templates.conf" ]; then
    echo "   kept your existing templates.conf (default is in templates.conf.example)"
else
    cp "$CONF_DIR/templates.conf.example" "$CONF_DIR/templates.conf"
    echo "   wrote default templates.conf"
fi
chmod 0644 "$UNIT_DIR/$UNIT" "$CONF_DIR/templates.conf" "$CONF_DIR/templates.conf.example"
systemctl --user daemon-reload
echo "   installed minimal-templating, minimal-templating-listen, service unit"

# ------------------------------------------------------------------ 3. base template
BASE=$(awk -F'=' '/^[[:space:]]*base[[:space:]]*=/{gsub(/[[:space:]]/,"",$2); print $2; exit}' "$CONF_DIR/templates.conf")
[ -n "$BASE" ] || { echo "no 'base =' in templates.conf" >&2; exit 1; }

echo "== $BASE"
if ! qvm-check --quiet "$BASE" 2>/dev/null; then
    echo "   not found: downloading and installing it (this takes a while)"
    qvm-template install "$BASE"
fi

echo "   dnf upgrade"
in_vm "$BASE" "dnf -y upgrade"

MASTER_VAR=
for kv in "${LISTS[@]}"; do
    if [ "${kv%%:*}" = master.dnf ]; then MASTER_VAR=${kv#*:}; fi
done
[ -n "$MASTER_VAR" ] || { echo "internal error: master.dnf not embedded" >&2; exit 1; }
PKGS=$(names "${!MASTER_VAR}"); check_names "$PKGS"
echo "   installing master.dnf packages: $PKGS"
in_vm "$BASE" "dnf -y install $PKGS"

in_vm "$BASE" "mkdir -p $D && chown root:root $D && chmod 0755 $D"
printf '%s\n' "$F_APPLY" | push "$BASE" "$D/apply" 0755
for kv in "${LISTS[@]}"; do
    name=${kv%%:*}; var=${kv#*:}
    printf '%s\n' "${!var}" | push "$BASE" "$D/$name" 0644
done
echo "   wrote $D/apply and lists: $(for kv in "${LISTS[@]}"; do printf '%s ' "${kv%%:*}"; done)"

qvm-shutdown --wait "$BASE"
echo "   $BASE shut down, disk saved"

# ------------------------------------------------------------------ 4. build
# Offline: everything keeps running while the templates and dvms are built.
echo "== building derived templates (your qubes keep running)"
if ! "$BIN/minimal-templating"; then
    echo
    echo "Build had failures (see ~/.local/state/minimal-templating/minimal-templating.log)."
    echo "Nothing has been switched over. Fix the lists, then re-run this script."
    exit 1
fi

# ------------------------------------------------------------------ 5. disposable templates
echo "== disposable templates"
# every name on every 'dvm =' line (a shared template lists several)
DVMS=$(awk -F'=' '/^[[:space:]]*dvm[[:space:]]*=/{n=split($2,a,/[[:space:]]+/); for(i=1;i<=n;i++) if(a[i]!="") print a[i]}' "$CONF_DIR/templates.conf")
for dvm in $DVMS; do
    qvm-check --quiet "$dvm" 2>/dev/null || { echo "   $dvm: missing, skipped"; continue; }
    in_vm "$dvm" "mkdir -p $RC_DIRS"
    extra=""
    qvm-shutdown --wait "$dvm"
    echo "   $dvm: rc.local.d, rc.local-early.d$extra"
done

# ------------------------------------------------------------------ 6. switch-over
if [ "$DO_SWITCH" -eq 1 ]; then
    echo "== switch-over (shutting down all qubes)"
    "$BIN/minimal-templating" --switch --yes || true
else
    echo "== switch-over skipped (run 'minimal-templating --switch' when ready)"
fi

# ------------------------------------------------------------------ 7. watcher on
# Its startup check finds last-update unchanged since the build above, so it
# doesn't rebuild again now; it just waits for the next base update.
echo "== watcher"
systemctl --user enable --now "$UNIT"
echo "   enabled: rebuilds automatically after every update of $BASE"

case ":$PATH:" in *":$HOME/.local/bin:"*) ;; *)
    echo "NOTE ~/.local/bin is not on your PATH; run ~/.local/bin/minimal-templating, or log out and in" ;;
esac

cat <<EOF

Done.
  minimal-templating --status          check every stack
  Qube Manager                         check the sys- qubes; old ones are kept as *-old
  qvm-remove <name>-old                delete each backup once you no longer need it
  systemctl --user disable --now $UNIT turn the automatic rebuild off
EOF
